// Package store is the persistence boundary: a SQLite-backed mailbox with
// IMAP identity semantics. Sequence numbers are derived (position in
// UID-ascending order) so deletions shift them, while UIDs are stored and
// stable. UIDVALIDITY is regenerated by Reset, invalidating all old UIDs.
// All methods are serialised by a single mutex, which is what gives
// concurrent observers one consistent order of mailbox events.
package store

import (
	"crypto/rand"
	"database/sql"
	"encoding/binary"
	"sort"
	"strings"
	"sync"

	_ "modernc.org/sqlite"

	"imapd/internal/errs"
)

// Message is one stored message with its derived sequence number.
type Message struct {
	UID     uint32
	Seq     uint32
	Flags   []string // canonical order: \Deleted before \Seen
	Content []byte
}

// Size is RFC822.SIZE: the exact byte length of the stored content.
func (m Message) Size() uint32 { return uint32(len(m.Content)) }

// Info is the SELECT-time mailbox snapshot.
type Info struct {
	Exists      uint32
	UIDValidity uint32
	UIDNext     uint32
}

// Event records one expunged message: the sequence number it had at the
// moment of its deletion and its (still stable) UID.
type Event struct {
	Seq uint32
	UID uint32
}

// SeedMessage is fixture input for Seed.
type SeedMessage struct {
	Content []byte
	Flags   []string
}

// KnownFlags is the declared flag set; anything else is an input error.
var KnownFlags = []string{"\\Deleted", "\\Seen"}

// Store is a SQLite-backed mailbox store. The zero-value-ready mutex
// serialises every operation; at this scale correctness of event order
// beats read parallelism.
type Store struct {
	db *sql.DB
	mu sync.Mutex
}

const schema = `
CREATE TABLE IF NOT EXISTS mailboxes (
  name        TEXT PRIMARY KEY,
  uidvalidity INTEGER NOT NULL,
  uidnext     INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS messages (
  mailbox TEXT NOT NULL,
  uid     INTEGER NOT NULL,
  flags   TEXT NOT NULL DEFAULT '',
  content BLOB NOT NULL,
  PRIMARY KEY (mailbox, uid)
);
`

// Open opens (creating if needed) the SQLite database at path.
func Open(path string) (*Store, error) {
	db, err := sql.Open("sqlite", "file:"+path+"?_pragma=busy_timeout(5000)")
	if err != nil {
		return nil, errs.Wrap(errs.CatInternal, "store.open", err, "cannot open database")
	}
	db.SetMaxOpenConns(1) // one connection: SQLite serialises writes anyway
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, errs.Wrap(errs.CatInternal, "store.open", err, "cannot create schema")
	}
	return &Store{db: db}, nil
}

func (s *Store) Close() error { return s.db.Close() }

// NewUIDValidity returns a random non-zero UIDVALIDITY (crypto/rand).
func NewUIDValidity() uint32 {
	var b [4]byte
	if _, err := rand.Read(b[:]); err != nil {
		// crypto/rand failure is a computation failure: fall back is
		// impossible, so surface it as a fixed non-zero constant and let
		// the caller's log correlation catch the anomaly.
		return 1
	}
	v := binary.LittleEndian.Uint32(b[:])
	if v == 0 {
		v = 1
	}
	return v
}

// Seed creates mailbox and inserts msgs with UIDs 1..n in order. A zero
// uidvalidity draws a random one. Seeding an existing mailbox is a state
// conflict.
func (s *Store) Seed(mailbox string, uidvalidity uint32, msgs []SeedMessage) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if uidvalidity == 0 {
		uidvalidity = NewUIDValidity()
	}
	if _, err := s.infoLocked(mailbox); err == nil {
		return errs.New(errs.CatState, "store.seed", "mailbox already exists")
	} else if errs.CategoryOf(err) != errs.CatState {
		return err
	}
	tx, err := s.db.Begin()
	if err != nil {
		return errs.Wrap(errs.CatInternal, "store.seed", err, "begin transaction failed")
	}
	defer tx.Rollback()
	if _, err := tx.Exec(`INSERT INTO mailboxes(name, uidvalidity, uidnext) VALUES(?,?,?)`,
		mailbox, uidvalidity, len(msgs)+1); err != nil {
		return errs.Wrap(errs.CatInternal, "store.seed", err, "insert mailbox failed")
	}
	for i, m := range msgs {
		if _, err := tx.Exec(`INSERT INTO messages(mailbox, uid, flags, content) VALUES(?,?,?,?)`,
			mailbox, i+1, joinFlags(m.Flags), m.Content); err != nil {
			return errs.Wrap(errs.CatInternal, "store.seed", err, "insert message failed")
		}
	}
	if err := tx.Commit(); err != nil {
		return errs.Wrap(errs.CatInternal, "store.seed", err, "commit failed")
	}
	return nil
}

// Reset deletes all messages and assigns a fresh UIDVALIDITY, which
// invalidates every previously issued UID. A zero uidvalidity draws a
// random one. Resetting a missing mailbox is a state conflict.
func (s *Store) Reset(mailbox string, uidvalidity uint32) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if uidvalidity == 0 {
		uidvalidity = NewUIDValidity()
	}
	if _, err := s.infoLocked(mailbox); err != nil {
		return err
	}
	tx, err := s.db.Begin()
	if err != nil {
		return errs.Wrap(errs.CatInternal, "store.reset", err, "begin transaction failed")
	}
	defer tx.Rollback()
	if _, err := tx.Exec(`DELETE FROM messages WHERE mailbox = ?`, mailbox); err != nil {
		return errs.Wrap(errs.CatInternal, "store.reset", err, "delete messages failed")
	}
	if _, err := tx.Exec(`UPDATE mailboxes SET uidvalidity = ?, uidnext = 1 WHERE name = ?`,
		uidvalidity, mailbox); err != nil {
		return errs.Wrap(errs.CatInternal, "store.reset", err, "update mailbox failed")
	}
	if err := tx.Commit(); err != nil {
		return errs.Wrap(errs.CatInternal, "store.reset", err, "commit failed")
	}
	return nil
}

// Replace atomically resets the mailbox (fresh UIDVALIDITY, invalidating
// all old UIDs) and seeds msgs with UIDs 1..n. It is the fixture-reload
// operation; a zero uidvalidity draws a random one.
func (s *Store) Replace(mailbox string, uidvalidity uint32, msgs []SeedMessage) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if uidvalidity == 0 {
		uidvalidity = NewUIDValidity()
	}
	tx, err := s.db.Begin()
	if err != nil {
		return errs.Wrap(errs.CatInternal, "store.replace", err, "begin transaction failed")
	}
	defer tx.Rollback()
	if _, err := tx.Exec(`DELETE FROM messages WHERE mailbox = ?`, mailbox); err != nil {
		return errs.Wrap(errs.CatInternal, "store.replace", err, "delete messages failed")
	}
	if _, err := tx.Exec(`INSERT INTO mailboxes(name, uidvalidity, uidnext) VALUES(?,?,?)
		ON CONFLICT(name) DO UPDATE SET uidvalidity = excluded.uidvalidity, uidnext = excluded.uidnext`,
		mailbox, uidvalidity, len(msgs)+1); err != nil {
		return errs.Wrap(errs.CatInternal, "store.replace", err, "upsert mailbox failed")
	}
	for i, m := range msgs {
		if _, err := tx.Exec(`INSERT INTO messages(mailbox, uid, flags, content) VALUES(?,?,?,?)`,
			mailbox, i+1, joinFlags(m.Flags), m.Content); err != nil {
			return errs.Wrap(errs.CatInternal, "store.replace", err, "insert message failed")
		}
	}
	if err := tx.Commit(); err != nil {
		return errs.Wrap(errs.CatInternal, "store.replace", err, "commit failed")
	}
	return nil
}

// Select returns the mailbox snapshot, or CatState if it does not exist.
func (s *Store) Select(mailbox string) (Info, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.infoLocked(mailbox)
}

func (s *Store) infoLocked(mailbox string) (Info, error) {
	var info Info
	err := s.db.QueryRow(`SELECT uidvalidity, uidnext FROM mailboxes WHERE name = ?`, mailbox).
		Scan(&info.UIDValidity, &info.UIDNext)
	if err == sql.ErrNoRows {
		return Info{}, errs.New(errs.CatState, "store.select", "no such mailbox")
	}
	if err != nil {
		return Info{}, errs.Wrap(errs.CatInternal, "store.select", err, "query failed")
	}
	if err := s.db.QueryRow(`SELECT COUNT(*) FROM messages WHERE mailbox = ?`, mailbox).
		Scan(&info.Exists); err != nil {
		return Info{}, errs.Wrap(errs.CatInternal, "store.select", err, "count failed")
	}
	return info, nil
}

// List returns all messages of mailbox ordered by UID, with sequence
// numbers assigned as position 1..n. This is the single place where the
// seq↔UID mapping is derived, so every observer computes the same mapping.
func (s *Store) List(mailbox string) ([]Message, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, err := s.infoLocked(mailbox); err != nil {
		return nil, err
	}
	return s.listLocked(mailbox)
}

// UpdateFlags adds (add=true) or removes flags on the given UIDs and
// returns the resulting flag set per actually-existing UID. Unknown flags
// are an input error; a missing mailbox is a state conflict; unknown UIDs
// are silently skipped per IMAP STORE semantics.
func (s *Store) UpdateFlags(mailbox string, uids []uint32, add bool, flags []string) (map[uint32][]string, error) {
	for _, f := range flags {
		if !isKnownFlag(f) {
			return nil, errs.New(errs.CatInput, "store.flags", "unsupported flag "+f)
		}
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, err := s.infoLocked(mailbox); err != nil {
		return nil, err
	}
	msgs, err := s.listLocked(mailbox)
	if err != nil {
		return nil, err
	}
	want := make(map[uint32]bool, len(uids))
	for _, u := range uids {
		want[u] = true
	}
	out := make(map[uint32][]string)
	for _, m := range msgs {
		if !want[m.UID] {
			continue
		}
		next := applyFlags(m.Flags, flags, add)
		if joinFlags(next) != joinFlags(m.Flags) {
			if _, err := s.db.Exec(`UPDATE messages SET flags = ? WHERE mailbox = ? AND uid = ?`,
				joinFlags(next), mailbox, m.UID); err != nil {
				return nil, errs.Wrap(errs.CatInternal, "store.flags", err, "update failed")
			}
		}
		out[m.UID] = next
	}
	return out, nil
}

// Expunge deletes every \Deleted message and reports one Event per
// deletion, in deletion order, each carrying the sequence number the
// message had at the moment it was removed (earlier removals shift later
// ones down). This is the delete-shift-renumber core of the service.
func (s *Store) Expunge(mailbox string) ([]Event, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, err := s.infoLocked(mailbox); err != nil {
		return nil, err
	}
	msgs, err := s.listLocked(mailbox)
	if err != nil {
		return nil, err
	}
	var events []Event
	var removed uint32
	for _, m := range msgs {
		if !hasFlag(m.Flags, "\\Deleted") {
			continue
		}
		if _, err := s.db.Exec(`DELETE FROM messages WHERE mailbox = ? AND uid = ?`, mailbox, m.UID); err != nil {
			return nil, errs.Wrap(errs.CatInternal, "store.expunge", err, "delete failed")
		}
		events = append(events, Event{Seq: m.Seq - removed, UID: m.UID})
		removed++
	}
	return events, nil
}

// listLocked is List without the lock; callers must hold s.mu.
func (s *Store) listLocked(mailbox string) ([]Message, error) {
	rows, err := s.db.Query(`SELECT uid, flags, content FROM messages WHERE mailbox = ? ORDER BY uid`, mailbox)
	if err != nil {
		return nil, errs.Wrap(errs.CatInternal, "store.list", err, "query failed")
	}
	defer rows.Close()
	var out []Message
	for rows.Next() {
		var m Message
		var flags string
		if err := rows.Scan(&m.UID, &flags, &m.Content); err != nil {
			return nil, errs.Wrap(errs.CatInternal, "store.list", err, "scan failed")
		}
		m.Flags = splitFlags(flags)
		m.Seq = uint32(len(out) + 1)
		out = append(out, m)
	}
	if err := rows.Err(); err != nil {
		return nil, errs.Wrap(errs.CatInternal, "store.list", err, "iteration failed")
	}
	return out, nil
}

func isKnownFlag(f string) bool {
	for _, k := range KnownFlags {
		if k == f {
			return true
		}
	}
	return false
}

func hasFlag(flags []string, want string) bool {
	for _, f := range flags {
		if f == want {
			return true
		}
	}
	return false
}

func applyFlags(have, delta []string, add bool) []string {
	set := make(map[string]bool, len(have)+len(delta))
	for _, f := range have {
		set[f] = true
	}
	for _, f := range delta {
		set[f] = add
	}
	out := make([]string, 0, len(set))
	for _, k := range KnownFlags { // canonical order keeps output deterministic
		if set[k] {
			out = append(out, k)
		}
	}
	return out
}

func joinFlags(flags []string) string {
	sorted := make([]string, 0, len(flags))
	for _, k := range KnownFlags {
		for _, f := range flags {
			if f == k {
				sorted = append(sorted, f)
			}
		}
	}
	return strings.Join(sorted, " ")
}

func splitFlags(s string) []string {
	if s == "" {
		return nil
	}
	f := strings.Split(s, " ")
	sort.Strings(f) // defensive; joinFlags already stores canonical order
	return f
}
